"""Explicit, dimensioned Pepper's Ghost reflector project, not free-air holography."""
import math
from .workshop import DEFAULT
from .workshop_free import result

def design(body):
 if not isinstance(body,dict)or set(body)-{'base','opening'}:raise ValueError('Nur äußere Breite und kleine Öffnung angeben.')
 base=body.get('base',60);opening=body.get('opening',10)
 if any(type(n)not in {float,int}or not math.isfinite(n)for n in [base,opening])or not 40<=base<=160 or not 4<=opening<=30 or opening>=base*.6:raise ValueError('Außenbreite 40–160 mm; kleine Öffnung 4–30 mm und kleiner als 60 % der Außenbreite.')
 rise=(base-opening)/2;slant=math.hypot(rise,rise);offset=(base+opening)/4
 parts=[]
 for name,pos,rot in [('Vorderseite',[0,rise/2,offset],[45,0,0]),('Rückseite',[0,rise/2,-offset],[-45,0,0]),('Rechte Seite',[offset,rise/2,0],[90,45,-90]),('Linke Seite',[-offset,rise/2,0],[90,-45,90])]:
  parts.append({'name':name,'shape':'extrude','size':[base,slant,.5],'position':pos,'rotation':rot,'material':'plastic','outline':[[-opening/base/2,-.5],[opening/base/2,-.5],[.5,.5],[-.5,.5]]})
 data=result({'title':'Smartphone-Reflektor · Pepper’s Ghost','parts':parts,'features':['Vier transparente Flächen spiegeln ein Motiv vom Smartphone-Display.','Ein schwebend wirkendes Bild im Inneren; keine Projektion frei in den Raum.'],'explanation':'Hier baust du ein echtes kleines optisches Demonstrationsgerät: vier klare Trapeze stehen bei 45° um eine kleine Öffnung. Das Display darunter liefert das Bild. Die Wirkung ist eine Spiegelungsillusion, die oft Hologramm genannt wird.','steps':['Prüfe, ob dein Smartphone-Display mindestens '+str(base)+' mm nutzbare Breite hat; der große Rand darf nicht überstehen.','Zeichne vier gleiche Trapeze: große Kante '+str(base)+' mm, kleine Kante '+str(opening)+' mm, senkrechter Abstand auf der flachen Folie '+str(round(slant,1))+' mm. Zuerst Papiermuster falten und die Passung prüfen.','Schneide die vier Teile aus klarer PET-Folie und verbinde die Seitenkanten vorsichtig mit transparentem Klebeband. Die schmalen Kanten bilden unten die kleine quadratische Öffnung. Bei scharfen Werkzeugen Hilfe holen.','Lege eine saubere Schutzfolie aufs Display. Stelle den Reflektor mittig mit der kleinen Öffnung nach unten auf. Keine scharfen Kanten auf das Glas setzen.','Öffne das vierfache Testmotiv, stelle die Displayhelligkeit passend ein und dunkle den Raum ab. Das Motiv wird an den schrägen Flächen gespiegelt.']},{**DEFAULT,'material':'plastic'})
 data['supplies']=[{'name':p['name'],'size':p['size'],'material':'Klare ungetönte PET-Folie, etwa 0,5 mm'}for p in data['parts']]
 data['tools']=['Lineal, Papiermuster, geeignete Schere, transparentes Klebeband, Displayschutz.'];data['decisions']=['Konkretes bereitgestelltes Bauprojekt mit geometrisch berechneten Maßen; keine neu erfundene KI-Konstruktion.','45° Flächenneigung; senkrechte Gerätehöhe '+str(round(rise,1))+' mm.','Vor dem Zuschneiden Papiermuster und tatsächliche Displaygröße prüfen.'];data['limits']='Optisches Demonstrationsprojekt. Keine frei schwebende volumetrische Projektion. Bildqualität hängt von Folie, Display, Motiv und Raumlicht ab; nicht auf deiner Hardware getestet.';data['brief']='Smartphone-Reflektor bauen';data['project_kind']='phone_reflector';data['project_dimensions']={'base':base,'opening':opening};data['reply']='Sir, hier ist ein konkretes Bauprojekt mit vier Teilen, Zuschnittmaßen, Materialliste und Anleitung. Öffne „Anleitung direkt ansehen“ und das vierfache Testmotiv.';return data


def guide(body):
 """Readable physical build plan independent of local-model/3D availability.

 The optical mock-up can be made from measured paper templates. A self-contained
 powered device remains a parts-dependent integration project, not a promised
 40-euro kit or an implemented gesture system.
 """
 if not isinstance(body,dict)or set(body)-{'budget','inventory'}:raise ValueError('Bitte nur Budget und vorhandene Geräte angeben.')
 budget=body.get('budget',40);inventory=body.get('inventory','')
 if type(budget)not in {int,float}or not math.isfinite(budget)or not 0<budget<=100000:raise ValueError('Bitte ein positives Budget bis 100000 Euro angeben.')
 if not isinstance(inventory,str)or len(inventory)>1500:raise ValueError('Vorhandene Geräte bitte mit höchstens 1500 Zeichen beschreiben.')
 sections=[
  {'title':'1 · Was du tatsächlich baust','text':'Ein rundes Tischgehäuse mit eigenem Display und einer schrägen transparenten Fläche. Das Displaybild wird an dieser Fläche gespiegelt und wirkt im dunklen Inneren schwebend. Das heißt Pepper’s Ghost. Es ist kein frei im Raum erzeugtes, fühlbares Lichtobjekt.','steps':['Das Display liegt waagerecht im Sockel und zeigt ein helles Motiv auf schwarzem Hintergrund.','Eine klare Scheibe steht ungefähr 45° über dem Display: ihre obere Kante zeigt nach vorne zu dir, ihre untere Kante nach hinten zum dunklen Hintergrund. Du schaust von vorne durch die Scheibe.','Das Gehäuse kann rund sein. Ein einzelner Reflektor hat trotzdem einen bevorzugten Blickwinkel von vorne; eine Rundumsicht ist damit nicht versprochen.']},
  {'title':'2 · Dein Budget und vorhandene Geräte','text':'Dein maximales Gesamtbudget beträgt '+str(budget)+' Euro. Für ein eigenständiges Gerät müssen Display, Rechner, Stromversorgung und bei Handgesten auch Kamera im Gerät zusammenarbeiten. Dafür ist hier weder ein vollständiger Einkaufspreis noch eine passende Kombination geprüft.','steps':['Notiere die genauen Modellnamen deines vorhandenen Displays, Rechners und deiner Kamera. Deine aktuellen Angaben: '+(inventory.strip()or'Noch keine Geräte eingetragen.'),'Rechne auch Netzteile, Bildschirmadapter, Kabel, Reflektorfolie, Gehäusematerial und Befestigungen zum Gesamtpreis.','Kaufe noch keine Elektronik nur anhand dieser Liste. Prüfe zunächst, ob Display und Kamera mit dem konkreten Rechner funktionieren.','Wenn Display oder Rechner fehlen, ist die Machbarkeit innerhalb deines Budgets offen. Ein benötigter externer Mac wäre kein eigenständiges Tischgerät. Ein Handy ist für diesen Entwurf nicht vorgesehen.']},
  {'title':'3 · Erst die optische Wirkung prüfen','text':'Beginne mit einem herausnehmbaren Pappmodell, nicht mit dem fertigen Gehäuse. Damit prüfst du Spiegelung und Sichtfeld, bevor du Material zuschneidest.','steps':['Stelle dein bereits vorhandenes, geeignetes Display sicher waagerecht auf eine nicht kratzende Unterlage. Halte Lüftungsöffnungen frei und belaste das Displayglas nicht.','Zeige nur ein einfaches helles Motiv auf schwarzem Hintergrund. Arbeite zunächst in einem abgedunkelten Raum.','Halte ein kleines Stück klare PET-Folie mit Pappstützen bei ungefähr 45° über das Motiv. Die obere Kante liegt vorne bei dir, die untere hinten am dunklen Hintergrund. Die gesamte Folie bleibt mit Abstand über dem Display; auch die hintere untere Kante berührt es nicht. Stelle hinter die Folie schwarze Pappe.','Betrachte das Bild von vorne. Verschiebe nur Folie und Motiv, bis die Spiegelung vollständig sichtbar ist. Ein Doppelbild kann durch zwei reflektierende Oberflächen entstehen; dünnere geeignete Folie kann helfen, eine gute Wirkung ist aber nicht garantiert.','Wenn das Bild gespiegelt erscheint, muss das Motiv in der Anzeige gespiegelt werden. Dieser Test weist nur die Optik nach, nicht die Gestensteuerung.']},
  {'title':'4 · Papiermuster mit nachvollziehbaren Maßen','text':'Die Maße richten sich nach deinem tatsächlichen Display. Alle Angaben beziehen sich auf Millimeter. Ein Papiermuster darf angepasst werden, ohne Elektronik zu verändern.','steps':['Miss die gewünschte Motivfläche: W ist ihre Breite, H ihre Tiefe auf dem liegenden Display. Miss außerdem die äußere Breite A und Tiefe B des vollständigen Displaygehäuses einschließlich Steckern.','Für ein erstes Muster nimm eine Scheibenbreite W + 20 und einen waagerechten sowie senkrechten Abstand H + 20. Die schräge Scheibenhöhe beträgt ungefähr 1,414 × (H + 20). Die zusätzlichen 20 mm sind ein Test-Rand, keine Garantie für dein Sichtfeld.','Zeichne zwei gleiche rechtwinklige Pappdreiecke: beide kurzen Kanten H + 20, die schräge Kante wie oben berechnet. Stelle sie seitlich der Motivfläche auf. Ihre schrägen Kanten halten die Folie bei 45°: die hohe Seite zeigt nach vorne, die niedrige nach hinten. Hebe die ganzen Stützen auf eigenen Abstandshaltern so an, dass auch die niedrige Kante frei über dem Display bleibt.','Beispiel nur für eine 100 × 60 mm große Motivfläche: Folie zunächst 120 × 113,1 mm; seitliche Pappstützen je 80 × 80 mm mit 113,1 mm langer Schrägkante. Übertrage diese Beispielmaße nicht ungeprüft auf dein Display.','Zeichne den runden Sockel so groß, dass Displaygehäuse, Stützen und Steckerkabel vollständig hineinpassen. Als Startwert für ein zentriertes Rechteck brauchst du mindestens seine Diagonale √(Breite² + Tiefe²), zuzüglich Platz für Rand und Kabel. Prüfe jeden Platzbedarf mit echten Pappteilen.']},
  {'title':'5 · Einen runden Sockel und die Halterung bauen','text':'Die erste Gehäuseversion ist eine mechanische Pappkonstruktion. Schneide das Material getrennt von angeschlossenen Geräten; bei scharfen Werkzeugen Hilfe holen.','steps':['Schneide eine runde Grundplatte aus stabiler Pappe und einen zweiten Ring als oberen Rand. Markiere darauf das Display, die beiden Stützen und alle Kabelwege.','Verbinde Grundplatte und Ring mit kurzen Pappstreifen. Lasse den Sockel nach hinten oder unten zum Öffnen zugänglich. Mache die Vorderseite oberhalb des Sockels zur Sichtöffnung.','Klebe die beiden Dreieckstützen auf eigene Auflagen im Sockel, nicht auf das Display. Prüfe mit einer Pappscheibe, dass die Halterung nicht auf Elektronik drücken kann.','Lege die klare PET-Scheibe auf die Schrägkanten und sichere sie am Rand mit ablösbarem Klebeband. Sie darf nicht auf den Bildschirm rutschen. Scharfe Kanten abdecken.','Setze hinter die Scheibe einen dunklen, matten Hintergrund. Probiere das Motiv erneut. Erst wenn Blickwinkel, Stabilität und Kabel passen, kannst du ein dauerhafteres Material und dessen Befestigung auswählen.']},
  {'title':'6 · Eigenständige Elektronik richtig einplanen','text':'Dieser Teil kann ohne die genauen Gerätemodelle keine belastbare Anschlussanleitung enthalten. Es gibt keine pauschal passende Displayplatine, Pinbelegung oder Stromversorgung.','steps':['Prüfe in den Herstellerunterlagen, welche Bildschirmschnittstelle und welche Versorgung dein Display braucht. Stecke nur dafür vorgesehene, passende Kabel ein.','Prüfe, ob der eigene Rechner den Bildschirm ansteuert und das Motiv lokal anzeigen kann. Plane erst danach seinen Platz im Sockel.','Nutze die vorgesehenen unbeschädigten Netzteile. Öffne keine Netzteile und baue keine eigene Netzspannungsverdrahtung. Akkus und Ladeelektronik sind kein Bestandteil dieser Anleitung.','Lasse Lüftungsöffnungen, Steckverbindungen und Ein-/Ausschalter zugänglich. Prüfe Wärme und Standfestigkeit, bevor du das Gehäuse schließt.','Ein Gerät, das nur über einen externen Mac rechnet oder ein Bild erhält, hat die gewünschte Eigenständigkeit noch nicht erreicht.']},
  {'title':'7 · Handgesten sind eine eigene technische Aufgabe','text':'Eine transparente Scheibe erkennt keine Hände. Eine Kamera muss die Hand tatsächlich sehen und eine passende lokale Software muss Handposition und Geste auswerten. Für dieses neue Tischgerät ist hier noch keine solche Steuerung implementiert oder getestet.','steps':['Plane die Kamera so, dass sie deine Hand vor dem Gerät sehen kann, ohne die Sicht auf die Spiegelung zu verdecken. Das Objektiv darf nicht in die Pappe zeigen.','Prüfe zunächst das normale Kamerabild auf dem vorgesehenen Rechner. Beleuchtung für die Hand und Dunkelheit für die Spiegelung können einander widersprechen; teste beides am offenen Modell.','Lege erst danach wenige konkrete Aktionen fest: zum Beispiel links/rechts für Motivwechsel und eine bewusste Auswahlgeste. Eine unbeabsichtigte Bewegung darf nicht sofort eine Aktion auslösen.','Die Zuordnung von Geste zu Bildinhalt muss für die ausgewählte Kamera und den Rechner umgesetzt und geprüft werden. Diese Bauanleitung allein schaltet noch kein Handtracking frei.','Bis diese Software funktioniert, kannst du die optische Vorschau über vorhandene Bedienelemente am Rechner testen. Das ist ein Zwischenschritt und erfüllt noch nicht deinen Wunsch nach direkter Handbedienung.']},
  {'title':'8 · Prüfliste vor einem fertigen Gerät','text':'Ein sichtbares Reflexionsbild ist ein erster Teilerfolg. Ein fertiges Gerät muss zusätzlich eigenständig, stabil und tatsächlich bedienbar sein.','steps':['Motiv sichtbar: Teste von deinem üblichen Sitzplatz und bei deinem Raumlicht. Passt die komplette Spiegelung in die Sichtöffnung?','Mechanik: Bleiben Folie, Stützen und Sockel ohne Druck auf dem Display sicher an ihrem Platz? Sind alle Schnittkanten abgedeckt?','Elektronik: Funktioniert das ausgewählte Display mit dem ausgewählten eigenen Rechner und dessen vorgesehenen Netzteilen? Sind Kabel und Lüftung frei?','Gesten: Funktionieren die vereinbarten Aktionen mit deiner Hand zuverlässig? Wenn nicht, markiere die Gestensteuerung ausdrücklich als noch offen.','Kosten: Addiere nachprüfbare aktuelle Einzelpreise einschließlich Versand und bereits vorhandener Teile. Erst dann lässt sich bestätigen, ob dein Gesamtbudget eingehalten wird.']},
 ]
 return {'title':'Dein Hologramm-Tischgerät · Bauanleitung und offene Teile','summary':'Du kannst den optischen Aufbau und ein rundes Pappgehäuse anhand dieser Schritte selbst erproben. Ein vollständiges eigenständiges Gerät innerhalb deines Budgets samt Handtracking ist damit noch nicht zugesagt.','budget':budget,'inventory':inventory.strip(),'sections':sections,'shopping':['Bereits vorhandenes geeignetes Display: Modell, Außenmaße, Bildanschluss und Versorgung zuerst feststellen.','Eigener kleiner Rechner mit passendem Bildschirmanschluss; konkrete Kompatibilität und Preis sind offen.','Kamera, die am gewählten Rechner ein lesbares Bild liefert; Handtracking-Software muss dazu passen.','Dünne klare ungetönte PET-Folie für den ersten Spiegelungstest; tatsächliche optische Qualität vor Ort prüfen.','Stabile schwarze/matte Pappe, Papier, Lineal, geeignete Schneidwerkzeuge, ablösbares Klebeband und nicht kratzende Auflagen.','Passende vorhandene Hersteller-Netzteile und Kabel; keine geratenen Adapter oder Pinbelegungen.'],'limits':['Pepper’s Ghost ist eine Reflexionsillusion im Gehäuse, keine volumetrische Projektion und kein fühlbares Licht.','Keine geprüften aktuellen Einkaufspreise; Einhaltung deines Budgets und Kompatibilität der Elektronik sind noch offen.','Die optischen Beispielmaße sind Papiermuster. Sie müssen an dein tatsächliches Display und Sichtfeld angepasst werden.','Für dieses eigenständige Tischgerät ist die Handgestensteuerung noch nicht implementiert oder auf Hardware getestet.'],'reply':'Sir, hier ist die Bauanleitung direkt in Jarvis. Beginne beim optischen Papiermuster. Für die fertige eigenständige Elektronik brauche ich anschließend die genauen Modelle deiner vorhandenen Geräte; Handtracking ist noch ein offener Teil.'}
